targets.rawSql:
SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as "平均",domain
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip}
GROUP BY time,domain
ORDER BY time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps, domain
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip}
	GROUP BY time,domain
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, sum(request_length) * 8 / ${cal_interval} as "今日最大请求量"
FROM ${project}
PREWHERE toDate(timestamp) = today() and ${server_ip} and ${domain}
GROUP BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, sum(response_length) * 8 / ${cal_interval} as "今日最大返回量"
	FROM ${project}
	PREWHERE toDate(timestamp) = today() and ${server_ip} and ${domain}
GROUP BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS "今日最大QPS"
	FROM ${project}
	PREWHERE toDate(timestamp) = today() and ${server_ip} and ${domain}
	GROUP BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,countIf(status<400)/count() *100 as "请求成功率"
FROM ${project} 
PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
group by time
order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count()/${cal_interval} AS "当前QPS"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
	GROUP BY time
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as "整体响应时间"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
GROUP BY time
ORDER BY time

SELECT count()/10000 as "今日总PV(万)"
FROM ${project}
	PREWHERE toDate(timestamp) = today() and ${server_ip} and ${domain}

SELECT COUNT(DISTINCT client_ip) AS "今日总UV"
FROM ${project}
PREWHERE toDate(timestamp) = today() and ${server_ip} and ${domain}

	SELECT toStartOfInterval(timestamp, INTERVAL 60 SECOND) AS time, COUNT(DISTINCT client_ip) AS "每分钟UV"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS "QPS"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,
  quantileExact(0.99)(responsetime) as P99
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,
  quantileExact(0.90)(responsetime) as P90
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,
  quantileExact(0.50)(responsetime) as P50
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,
  quantileExact(0.75)(responsetime) as P75
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,
  quantileExact(0.95)(responsetime) as P95
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as "平均"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

	SELECT
	  `top_path` as TOP_Path, COUNT() AS PV, COUNT(DISTINCT client_ip) as "UV",avg(response_length) as "平均返回"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
	GROUP BY `top_path`
  order by COUNT() DESC

SELECT
  `top_path` as TOP_Path,avg(responsetime) as "指定状态响应时间"
FROM ${project}
PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY `top_path`

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, upstreamhost, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time,upstreamhost
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps, upstreamhost
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time,upstreamhost
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps, '整体'
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as rt,'整体'
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,upstreamhost,avg(responsetime) as rt
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,upstreamhost
ORDER BY time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, server_ip, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time,server_ip
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, server_ip, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time,server_ip
  order by time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, count() / ${cal_interval} AS avgqps,'整体'
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as rt, '整体'
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,server_ip,avg(responsetime) as rt
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,server_ip
ORDER BY time

	SELECT toStartOfHour(timestamp) AS time, count() AS "每小时PV"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

	SELECT toStartOfHour(timestamp) AS time, COUNT(DISTINCT client_ip) AS "每小时UV"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, sum(request_length) * 8 / ${cal_interval} as "每秒请求量"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, sum(response_length) * 8 / ${cal_interval} as "每秒返回量"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time
ORDER BY time

SELECT toStartOfMinute(timestamp) AS time, countIf(responsetime > 0.5) AS slow_requests
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
GROUP BY time
ORDER BY time

SELECT 
	domain as "域名",avg(responsetime) as "响应时间", count() as PV,COUNT(DISTINCT client_ip) as UV
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
	GROUP BY domain

SELECT
  `path` as "请求路径", avg(responsetime) as "平均响应时间",COUNT() AS PV, COUNT(DISTINCT client_ip) as "UV",avg(response_length) as "平均返回量"
FROM ${project}
WHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
GROUP BY `path`
HAVING PV >100
order by "平均响应时间" DESC
LIMIT 30;

SELECT
  `path` as "请求路径",quantileExact(0.90)(duration) as "P90NG处理时间",avg(response_length) as "平均返回量", avg(responsetime) as "平均响应时间",COUNT() AS PV, COUNT(DISTINCT client_ip) as "UV"
FROM ${project}
PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
GROUP BY `path`
HAVING PV > 10
order by "P90NG处理时间" DESC
LIMIT 30;

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as "平均",top_path
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,top_path
ORDER BY time

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, top_path, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time, top_path
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,quantileExact(0.90)(responsetime) as P90,top_path
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,top_path
ORDER BY time

SELECT toStartOfMinute(timestamp) AS time, top_path,sum(response_length) as "返回量"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
GROUP BY time, top_path
ORDER BY time

	SELECT
	  referer as Referer, 
    COUNT() as "PV", COUNT(DISTINCT client_ip) as "UV"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY referer
  order by COUNT() DESC
	LIMIT 30;

	SELECT
	  `path` as "请求路径", COUNT() AS PV, COUNT(DISTINCT client_ip) as "UV",avg(responsetime) as "平均响应时间",avg(response_length) as "平均返回量"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY `path`
  order by PV DESC
	LIMIT 30;

	SELECT
	  `path` as "请求路径",avg(response_length) as "平均返回量", avg(responsetime) as "平均响应时间",COUNT() AS PV, COUNT(DISTINCT client_ip) as "UV"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY `path`
  order by "平均返回量" DESC
	LIMIT 30;

	SELECT
	  client_ip as "用户IP", 
    COUNT() AS PV, COUNT(DISTINCT `path`) as "请求URL数",sum(response_length) as "接收数据量"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY client_ip
  order by PV DESC
	LIMIT 30;

SELECT client_region as "省份",client_city as "城市",avg(responsetime) as "响应时间",count() as "PV",COUNT(DISTINCT client_ip) as UV
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
group by client_region,client_city

	SELECT
	  client_region, 
    COUNT() AS "未解析"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY client_region

	SELECT
	  client_city, 
    COUNT() AS "未解析"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY client_city

	SELECT
	  client_os_family, 
    COUNT() AS "未解析"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain}
	GROUP BY client_os_family

	SELECT
	  client_browser_family, 
    COUNT() AS "未解析"
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY client_browser_family
  order by COUNT() DESC
	LIMIT 10;

	SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time, client_city, count() / ${cal_interval} AS avgqps
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
	GROUP BY time,client_city
  order by time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,avg(responsetime) as "平均",client_city
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,client_city
having count()/${cal_interval} > 1
ORDER BY time

SELECT toStartOfInterval(timestamp, INTERVAL ${cal_interval} SECOND) AS time,quantileExact(0.90)(responsetime) as P90,client_city
	FROM ${project}
	PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY time,client_city
having count()/${cal_interval} > 1
ORDER BY time

SELECT COUNT() AS PV, client_latitude as latitude ,client_longitude as longitude,client_city as "城市",client_region as "省份"
FROM ${project}
PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY client_latitude,client_longitude,client_city,client_region

SELECT avg(responsetime) as "响应时间", client_latitude as latitude ,client_longitude as longitude,client_city as "城市",client_region as "省份"
FROM ${project}
PREWHERE $__timeFilter(timestamp) and ${server_ip} and ${domain} and ${status}
GROUP BY client_latitude,client_longitude,client_region,client_city

